const jevStats = { n: 0, ms: 0 }; export const bump = (n, ms) => { jevStats.n += n; jevStats.ms += ms; $("#h-stats").textContent = ` このセッション: ${jevStats.n} 判定 / 平均 ${(jevStats.ms / jevStats.n).toFixed(0)} ms`; };

