const mdescOf = m => { if (!m) return ""; const dev = (m.size_mb || 999) <= 100 ? "スマホ・PC（100 MB 以下）" : "PC 向け（" + (m.size_mb || "?") + " MB、大）"; return `${m.kind === "jev_ja" ? "自作 JEV-JA" : "既存 Jev"} ・ ${m.language || "ja"} ・ ${m.size_mb ? m.size_mb + " MB" : ""} ・ ${dev}${m.license ? " ・ " + m.license : ""}${m.note ? " ・ " + m.note : ""}`; };
export async function loadIndex() { models = await listAllModels(); for (const id of ["#model", "#v-models", "#v-model2"]) { const s = $(id); if (!s) continue; s.innerHTML = ""; const groups = {}; for (const m of models) (groups[m.group] ??= []).push(m); for (const [g, ms] of Object.entries(groups)) { const og = document.createElement("optgroup"); og.label = g; for (const m of ms) { const o = document.createElement("option"); o.value = m.name; o.textContent = `${m.name}${m.size_mb ? " " + m.size_mb + "MB" : ""}${m.kind === "jev_ja" ? (m.trained ? " 学習済" : " 未学習") : ""}`; og.appendChild(o); } s.appendChild(og); } } await markStored(); $("#model").onchange(); }
export async function markStored() { const ks = new Set(await store.keys()); for (const o of $("#model").options) { const m = models.find(x => x.name === o.value); if (!m || m.kind === "open-jev-onnx") continue; const s = m.kind === "jev_ja" ? await isStored(o.value) : ks.has(`${o.value}/model.onnx`); o.textContent = o.textContent.replace(/ ・保存済$/, "") + (s ? " ・保存済" : ""); } }
export async function storageInfo() { try { const e = await navigator.storage.estimate(); const p = await navigator.storage.persisted?.(); const mb = await storedBytes(); $("#storage").textContent = `端末内: モデル ${(mb / 1e6).toFixed(0)} MB ・ サイト全体 ${(e.usage / 1e6).toFixed(0)} / ${(e.quota / 1e6).toFixed(0)} MB ・ 永続化 ${p ? "済" : "未"}`; } catch { } }
export async function offlineCheck() { const name = $("#model").value; const m = models.find(x => x.name === name); if (m?.kind !== "jev_ja") { $("#offline").textContent = ""; return; } const okModel = await isStored(name); const sw = navigator.serviceWorker?.controller; if (!sw) { $("#offline").textContent = okModel ? "モデル保存済" : ""; return; } navigator.serviceWorker.onmessage = ev => { if (ev.data?.type !== "offline-status") return; $("#offline").innerHTML = ev.data.ready && okModel ? `<span class="ok">✅ オフライン可</span>` : `<span class="warn">⚠️ オフライン準備: 未</span>`; }; sw.postMessage({ type: "offline-check", model: name }); }
$("#model").onchange = () => { offlineCheck(); const m = models.find(x => x.name === $("#model").value); $("#mchange").innerHTML = jev && m && m.name !== jev.name ? `<span class="warn">「読み込む」で <b>${esc(m.name)}</b> に切り替わります。</span>` : ""; $("#mdesc").textContent = mdescOf(m) + (isMobile && m && (m.size_mb || 0) > 100 ? " ⚠️ スマホには大きすぎる可能性" : ""); };
