export async function waitModel() { if (jev) return true; $("#msheet").classList.remove("hidden"); status("モデルを読み込み中…（初回のみ）"); if (!$("#load").disabled) $("#load").click(); for (let i = 0; i < 600; i++) { await new Promise(r => setTimeout(r, 500)); if (jev) return true; if ($("#mdot").classList.contains("err")) return false; } return false; }
export async function run(state, qs, c) { const r = jev.kind === "jev_ja" ? await jev.analyze(state, qs, c, curOpts()) : await jev.decide(state, qs, c, curOpts()); r.input = { state, context: c, questions: qs }; return r; }
export async function saveNote(e) { e.id = e.id || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`; e.time = e.time || new Date().toISOString(); e.device = e.device || navigator.userAgent; e.app_version = VERSION; e.notes = e.notes || ""; await store.expPut(e); return e.id; }

