const qb = $("#qb"); let qbCustom = false;
const slug = s => (s || "").replace(/[^\p{L}\p{N}]+/gu, "_").replace(/^_|_$/g, "").slice(0, 16) || "q";
function qCard(q) { const div = document.createElement("div"); div.className = "qcard"; const listLabel = q.type === "choice" ? "選択肢（1 行 1 つ）" : q.type === "score" ? "段階（低 → 高）" : null; const list = q.type === "choice" ? q.options : q.type === "score" ? q.levels : [];
  div.innerHTML = `<div class="hd"><select class="qt"><option value="choice">選択</option><option value="score">段階</option><option value="noul">はい/いいえ</option></select><input class="qi" placeholder="質問文" value="${esc(q.instructions || "")}"><button class="qdel small" title="削除">✕</button></div>${listLabel ? `<label>${listLabel}</label><textarea class="ql" style="min-height:50px">${esc(list.join("\n"))}</textarea>` : ""}<div class="small muted">id: <input class="qid" value="${esc(q.id || "")}" style="width:120px;display:inline;padding:2px 6px" placeholder="自動"></div>`;
  div.querySelector(".qt").value = q.type; div.querySelector(".qt").onchange = e => { const nq = readCard(div); nq.type = e.target.value; if (nq.type === "choice" && !nq.options) nq.options = nq.levels || ["A", "B"]; if (nq.type === "score" && !nq.levels) nq.levels = nq.options || ["低い", "中程度", "高い"]; div.replaceWith(qCard(nq)); syncJson(); };
  div.querySelector(".qdel").onclick = () => { div.remove(); syncJson(); }; div.querySelectorAll("input,textarea").forEach(el => el.oninput = () => { qbCustom = true; syncJson(); }); return div; }
function readCard(div) { const type = div.querySelector(".qt").value, instructions = div.querySelector(".qi").value; const id = div.querySelector(".qid").value.trim() || slug(instructions); const list = div.querySelector(".ql") ? div.querySelector(".ql").value.split("\n").map(s => s.trim()).filter(Boolean) : null; return type === "choice" ? { type, id, instructions, options: list } : type === "score" ? { type, id, instructions, levels: list } : { type, id, instructions }; }
export const readQuestions = () => $$("#qb .qcard").map(readCard).filter(q => q.instructions.trim() && (q.type === "noul" || (q.options || q.levels || []).length >= 2));
const syncJson = () => $("#p-q").value = JSON.stringify($$("#qb .qcard").map(readCard), null, 1);
