$("#p-run").onclick = async () => { if (!ready()) return; const s = $("#p-state").value.trim(); if (!s) { $("#p-state").focus(); return toast("文章を入れてください"); } if (!readQuestions().length) $("#p-set").onchange(); const qs = readQuestions(); status("判定中…"); $("#p-run").disabled = true; try { last = await run(s, qs, ctx()); rememberResult(last); renderVerify(last); renderViz(last); bump(qs.length, last.latency_ms); if (isMobile) $("#v-verdict").scrollIntoView({ behavior: "smooth", block: "start" }); } catch (e) { $("#p-out").innerHTML = `<div class="card bad">${esc(e.message)}</div>`; } $("#p-run").disabled = false; status(""); };
