$("#v-cite").onclick = async () => { if (!ready()) return; const s = $("#p-state").value.trim(), c = ctx(); if (!s || !c.length) return toast("文章と根拠（1 行以上）が必要です"); status("照合中…"); let h = ""; for (const line of c) { const r = await jev.decide(s, [CITATION_Q], [line], curOpts()); const a = r.answers[0]; bump(1, r.latency_ms); h += `<div class="ans" style="display:block"><div class="small">${esc(line.slice(0, 90))}</div><b class="${a.choice.startsWith("支持") ? "ok" : a.choice.startsWith("矛盾") ? "bad" : "muted"}">${esc(a.choice)}</b> <span class="conf ${confCls(a.confidence)}">${pc(a.confidence)}</span></div>`; } $("#v-cite-out").innerHTML = h; status(""); };
