$("#v-cross").onclick = async () => { if (!last) return toast("先に判定してください"); const name = $("#v-model2").value; if (!name || name === jev?.name) return toast("今と別のモデルを選んでください"); status(`${name} を読み込み中…`); try { const m = await loadModelByName(name, progress); const r = await m.decide(last.input.state, last.input.questions, last.input.context, curOpts()); let agree = 0; $("#v-cross-out").innerHTML = `<table>${last.answers.map((a, i) => { const b = r.answers[i]; const same = labJa(a) === labJa(b); if (same) agree++; return `<tr><td class="small">${esc(last.input.questions[i].instructions)}</td><td>${esc(labJa(a))}</td><td class="${same ? "ok" : "bad"}">${same ? "＝" : "≠"} ${esc(labJa(b))}</td></tr>`; }).join("")}</table><p class="hint">一致 ${agree}/${last.answers.length}（${esc(jev.name)} vs ${esc(name)}）。一致した問いはより確か。</p>`; } catch (e) { $("#v-cross-out").textContent = e.message; } progress(""); status(""); };
