export async function sendOut(text) { if (!text) return toast("送るものがありません"); const c = conf.load(); const targets = [c.discord && "discord", c.slack && "slack", navigator.share && "share", "copy"].filter(Boolean); const pick = targets.length > 1 ? prompt(`送り先: ${targets.join(" / ")}`, targets[0]) : targets[0]; if (!pick) return; try { if (pick === "discord") await sendDiscord(c.discord, text); else if (pick === "slack") await sendSlack(c.slack, text); else if (pick === "share") await shareText("JEV Lab", text); else await navigator.clipboard.writeText(text); toast(`送りました（${pick}）`); } catch (e) { toast("送信失敗: " + e.message); } }

