export function savedQueries() { try { const q = JSON.parse(localStorage.getItem("jev.queries") || "[]"); $("#o-saved").innerHTML = q.map(x => `<option value="${esc(x)}">`).join(""); return q; } catch { return []; } } savedQueries();
