const judgedPlain = () => oJudged?.map(j => j && Object.fromEntries(Object.entries(j).filter(([k]) => k !== "_ms").map(([k, a]) => [k, { label: lab(a), score: a.score, p_yes: a.p_yes, confidence: a.confidence }])));
export function labelItems() { const q = $("#o-q").value; const out = []; oItems.forEach((it, i) => { const L = oLabels[i]; if (it.error || !L || (!L.kind && !L.trust)) return; const qs = [], gold = {}; if (L.kind) { qs.push(OSINT_QUESTIONS(q)[1]); gold.kind = L.kind; } if (L.trust) { qs.push({ type: "score", id: "trust", instructions: "この情報の信頼性", levels: ["低", "中", "高"] }); gold.trust = L.trust; } if (qs.length) out.push({ id: `osint-${Date.now()}-${i}`, family: "osint_ja", split: "in_domain", state: `${it.title}\n${it.text}`, context: oGeo.slice(0, 3), meta: { query: q, source: it.source, url: it.url, time: it.time }, questions: qs, gold }); }); return out; }
function osintText() { if (!oItems.length) return ""; const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null; const top = [...oItems.keys()].filter(i => !oItems[i].error).sort((a, b) => (ts?.[b]?.score ?? 0) - (ts?.[a]?.score ?? 0)).slice(0, 5); const chk = oJudged ? [...oItems.keys()].filter(i => needsCheck(oItems[i], oJudged[i])) : []; return `【JEV 収集】${$("#o-q").value}（${oItems.filter(i => !i.error).length} 件）\n` + top.map(i => `・[${oItems[i].source}] ${(oItems[i].title || "").slice(0, 60)}${ts?.[i] ? ` 信頼性 ${(ts[i].score * 100).toFixed(0)}` : ""}${oJudged?.[i]?.kind ? " / " + oJudged[i].kind.choice : ""}\n  ${oItems[i].url}`).join("\n") + (chk.length ? `\n要確認 ${chk.length} 件` : ""); }
export async function importItems(items, label) { if (!items.length) return toast("取り込める投稿がありません"); oItems = items; oJudged = null; oClusters = null; oLabels = {}; oGeo = []; oFilter = "all"; $("#o-q").value = label; $("#u-q").value = label; $("#o-ctx").value = ""; uShow("#u-topic"); renderResults(); if (jev) await doJudge(); else toast("モデルを読み込むと JEV が仕分けます"); }

/* ================= 調べる（対象の調査） ================= */
const RECON_QUESTIONS = [
  { type: "noul", id: "legit", instructions: "この対象は公的機関・大手・正規の運営者のものと考えられるか" },
  { type: "score", id: "risk", instructions: "なりすまし・詐欺・不正の疑いの強さ", levels: ["0", "1", "2", "3", "4", "5"] },
  { type: "choice", id: "issue", instructions: "最も注意すべき点", options: ["登録が新しい", "送信認証が未設定", "脅威情報あり", "見た目が似た文字", "使い捨て・匿名の手段", "特に問題なし"] },
  { type: "noul", id: "need_more", instructions: "結論を出す前に追加の確認が必要か" }];
let reconResults = [];
const splitTargets = raw => { const toks = raw.split(/[,\n]/).map(x => x.trim()).filter(Boolean); const out = []; for (let i = 0; i < toks.length; i++) { if (/^-?\d+(\.\d+)?$/.test(toks[i]) && /^-?\d+(\.\d+)?$/.test(toks[i + 1] || "")) { out.push(`${toks[i]},${toks[i + 1]}`); i++; } else out.push(toks[i]); } return out.map(detectTarget); };
$("#r-run").onclick = async () => { const raw = $("#r-q").value.trim(); if (!raw) return; const targets = splitTargets(raw); reconResults = []; $("#r-out").innerHTML = ""; try { localStorage.setItem("jev.targets", JSON.stringify([raw, ...(JSON.parse(localStorage.getItem("jev.targets") || "[]")).filter(x => x !== raw)].slice(0, 20))); } catch { }
  for (const t of targets) { const box = document.createElement("div"); box.className = "card"; box.innerHTML = `<b>${esc(TARGET_TYPES[t.type] || t.type)}: ${esc(t.value)}</b> <span class="muted small r-st">取得中…</span>`; $("#r-out").appendChild(box); const st = box.querySelector(".r-st");
    try { if (t.type === "keyword") { box.innerHTML = `<p class="small">「${esc(t.value)}」は話題として収集します。</p>`; continue; } const R = await investigate(t, m => st.textContent = m); reconResults.push(R); box.replaceWith(renderRecon(R)); } catch (e) { box.innerHTML += `<p class="bad">失敗: ${esc(e.message)}</p>`; } }
  if (reconResults.length > 1) drawGraph(reconResults); status(""); };
function renderRecon(R) { const d = document.createElement("div"); d.className = "card"; const kv = rows => "<table>" + Object.entries(rows).filter(([, v]) => v != null && v !== "").map(([k, v]) => `<tr><td style="width:30%">${esc(k)}</td><td class="small">${/^https?:\/\//.test(String(v)) ? `<a href="${esc(v)}" target="_blank" rel="noopener">${esc(v)}</a>` : esc(String(v))}</td></tr>`).join("") + "</table>"; const cats = {}; for (const l of R.links) (cats[l.cat] ??= []).push(l);
  d.innerHTML = `<h2 style="margin-top:0">${esc(TARGET_TYPES[R.type] || R.type)}: ${esc(R.target.value)}</h2>${R.warnings.length ? `<div class="note"><b>注意</b><ul class="small" style="margin:4px 0 0 18px;padding:0">${R.warnings.map(w => `<li>${esc(w)}</li>`).join("")}</ul></div>` : ""}<div class="r-jev">${["domain", "url", "ip", "email"].includes(R.type) ? `<p class="hint">${jev ? "JEV が根拠を読んで判定中…" : "モデルを読み込むと JEV が「正規か／なりすましの疑い／注意点」を判定します"}</p>` : ""}</div>${R.cards.map(c => `<details ${R.cards.length <= 4 ? "open" : ""}><summary>${esc(c.title)}${c.url ? ` <a href="${esc(c.url)}" target="_blank" rel="noopener" class="small">開く</a>` : ""}</summary>${kv(c.rows)}</details>`).join("")}${R.evidence.length ? `<details><summary>根拠として使える要約（${R.evidence.length} 行）</summary><ul class="small">${R.evidence.map(e => `<li>${esc(e)}</li>`).join("")}</ul><button class="small r-ctx">→ 見極めるの根拠に入れる</button></details>` : ""}${Object.keys(cats).length ? `<details><summary>各サービスで開く（${R.links.length} リンク）</summary>${Object.entries(cats).map(([c, ls]) => `<p class="small"><b>${esc(c)}</b> ${ls.map(l => `<a href="${esc(l.url)}" target="_blank" rel="noopener"><button class="small">${esc(l.name)}</button></a>`).join(" ")}</p>`).join("")}</details>` : ""}${R.entities.length > 1 ? `<details><summary>関係図（${R.entities.length} 要素）</summary><canvas class="r-graph" width="720" height="360"></canvas></details>` : ""}<div class="chips"><span class="small muted">次に調べる:</span>${nextSteps(R).map(n => n.url ? `<a class="chip" href="${n.url}" target="_blank" rel="noopener" title="${esc(n.q || "")}">🔍 ${esc(n.name)}</a>` : `<span class="chip r-next" data-q="${esc(n.collect)}">🔎 ${esc(n.name)}</span>`).join("")}</div><div class="actbar"><button class="small r-json">JSON</button><button class="small r-note">ノートに保存</button></div>`;
  d.querySelectorAll(".r-next").forEach(c => c.onclick = () => { $("#u-q").value = c.dataset.q; uModeSel = "topic"; $("#u-run").click(); });
  d.querySelector(".r-ctx")?.addEventListener("click", () => { $("#p-ctx").value = [...ctx(), ...R.evidence].join("\n"); $("#p-ctx").oninput(); toast("見極めるの根拠に追加しました"); }); d.querySelector(".r-json").onclick = () => download(`recon-${R.type}-${Date.now()}.json`, JSON.stringify({ version: VERSION, time: new Date().toISOString(), ...R }, null, 1)); d.querySelector(".r-note").onclick = async () => { await saveNote({ kind: "recon", name: `調査: ${R.target.value}`, model: jev?.name, target: R.target, evidence: R.evidence, warnings: R.warnings, judged: R.judged || null }); toast("保存しました"); };
  const g = d.querySelector(".r-graph"); if (g) drawEntityGraph(g, [R]); const rj = d.querySelector(".r-jev"); if (jev && R.evidence.length >= 2) reconJudge(R, rj); return d; }
async function reconJudge(R, el) { const state = [...R.warnings.map(w => "注意: " + w), ...R.evidence].join("\n"); try { const r = await jev.decide(state, RECON_QUESTIONS, null, curOpts()); R.judged = r.answers.map(a => ({ id: a.id, label: lab(a), confidence: a.confidence })); const A = Object.fromEntries(r.answers.map(a => [a.id, a])); const risk = A.risk.score; bump(4, r.latency_ms); el.innerHTML = `<div class="verdict">${ring(1 - risk / 5, { size: 64, sub: "安全" })}<div><h3 class="${risk >= 3 ? "bad" : risk >= 1.5 ? "warn" : "ok"}">${risk >= 3 ? "疑いが強い：入力や送金をしない" : risk >= 1.5 ? "グレー：注意点を確認" : "問題は見当たらない"}</h3><div class="chips"><span class="flag ${A.legit.noul ? "good" : "alert"}">正規の運営者 ${A.legit.noul ? "✓" : "?"} ${pc(A.legit.confidence)}</span><span class="flag ${risk >= 3 ? "alert" : ""}">疑い ${risk.toFixed(1)}/5</span><span class="flag on">注意点: ${esc(A.issue.choice)}</span><span class="flag ${A.need_more.noul ? "alert" : ""}">追加確認 ${A.need_more.noul ? "必要" : "不要"}</span></div><span class="muted tiny">${esc(jev.name)} ・ ${r.latency_ms.toFixed(0)} ms ・ 端末内（根拠行だけを読んで判定）</span></div></div>`; } catch (e) { el.innerHTML = `<p class="muted small">JEV 判定失敗: ${esc(e.message)}</p>`; } }
function drawEntityGraph(c, results) { const g = c.getContext("2d"); const dark = document.documentElement.dataset.theme === "dark" || (matchMedia("(prefers-color-scheme:dark)").matches && document.documentElement.dataset.theme !== "light"); g.fillStyle = dark ? "#171b21" : "#fff"; g.fillRect(0, 0, c.width, c.height); const nodes = [], edges = []; const id = new Map(); const add = (t, v) => { const k = t + ":" + v; if (!id.has(k)) { id.set(k, nodes.length); nodes.push({ t, v }); } return id.get(k); }; for (const R of results) { const root = add(R.type, R.target.value); for (const e of R.entities.slice(0, 40)) { if (e.value === R.target.value) continue; edges.push([root, add(e.type, e.value), e.rel]); } }
  const col = { domain: "#0b6e99", host: "#0f766e", ip: "#b45309", email: "#7c3aed", username: "#be123c", place: "#15803d", org: "#6b7280", url: "#0b6e99", coords: "#15803d" }; const Wd = c.width, H = c.height; const pos = nodes.map((n, i) => { const roots = results.map(R => R.type + ":" + R.target.value); const ri = roots.indexOf(n.t + ":" + n.v); if (ri >= 0) return { x: Wd / 2 + (results.length > 1 ? (ri - (results.length - 1) / 2) * 220 : 0), y: H / 2 }; const a = i / nodes.length * Math.PI * 2; return { x: Wd / 2 + Math.cos(a) * (Wd / 2 - 70), y: H / 2 + Math.sin(a) * (H / 2 - 30) }; });
  g.font = "11px system-ui"; g.strokeStyle = dark ? "#2a3039" : "#d9dde3"; for (const [a, b] of edges) { g.beginPath(); g.moveTo(pos[a].x, pos[a].y); g.lineTo(pos[b].x, pos[b].y); g.stroke(); } nodes.forEach((n, i) => { g.fillStyle = col[n.t] || "#6b7280"; g.beginPath(); g.arc(pos[i].x, pos[i].y, 6, 0, 7); g.fill(); g.fillStyle = dark ? "#e6e8eb" : "#1a1d21"; g.fillText(String(n.v).slice(0, 28), pos[i].x + 8, pos[i].y + 4); }); }
function drawGraph(results) { const c = document.createElement("canvas"); c.width = 900; c.height = 420; const d = document.createElement("div"); d.className = "card"; d.innerHTML = "<h2 style='margin-top:0'>関係図（すべての対象）</h2>"; d.appendChild(c); $("#r-out").prepend(d); drawEntityGraph(c, results); }

/* ================= 統合入力 ================= */
export let uModeSel = "auto"; const uMode = () => uModeSel === "auto" ? uDetect(true) : uModeSel;
const segSel = m => $$("#u-modes button").forEach(x => x.classList.toggle("on", x.dataset.m === m));
