/* 検索式（コピペ用）と OSINT ツールリンク */
export function dorkList(q, d) { const P = plan(q); const lib = DORK_LIBRARY.map(x => ({ cat: x.cat, name: x.name, q: buildFromLibrary(x, q, d || q) })); const seen = new Set(); return [...P.dorks.map(x => ({ cat: "おすすめ（" + P.label + "）", name: x.name, q: x.q })), ...lib].filter(x => { if (seen.has(x.q)) return false; seen.add(x.q); return true; }); }
export function dorkHtml(list) { let cat = ""; return list.map(x => (x.cat !== cat ? `<p class="small b" style="margin:8px 0 2px">${esc(cat = x.cat)}</p>` : "") + `<div class="dork"><div><span class="tiny muted">${esc(x.name)}</span><code>${esc(x.q)}</code></div><span class="b"><button class="d-cp" data-q="${esc(x.q)}">コピー</button><a href="https://www.google.com/search?q=${encodeURIComponent(x.q)}" target="_blank" rel="noopener"><button>Google</button></a><a href="https://www.bing.com/search?q=${encodeURIComponent(x.q.replace(/\bintext:/g, "inbody:").replace(/\s(after|before):\S+/g, ""))}" target="_blank" rel="noopener"><button>Bing</button></a></span></div>`).join(""); }
