function renderDorks(q, d) { const list = dorkList(q, d); const box = $("#u-dorks"); const rec = list.filter(x => x.cat.startsWith("おすすめ")), lib = list.filter(x => !x.cat.startsWith("おすすめ")); box.innerHTML = `<div class="card"><b class="small">🔍 検索式（コピペで検索）</b> <span class="tiny muted">「${esc(q)}」から自動生成</span><div class="actbar"><button class="small d-all">すべてコピー</button><button class="small u-compose">条件をボタンで足す</button></div>${dorkHtml(rec)}<details><summary class="small">用途別 ${lib.length} 式</summary>${dorkHtml(lib)}</details></div>`; wireDork(box, list); }
const fillUrl = (u, value, d) => u.replace(/\{q\}/g, encodeURIComponent(value)).replace(/\{d\}/g, encodeURIComponent(d)).replace(/\{lat\}|\{lon\}/g, "").replace(/\{b64\}/g, btoa(unescape(encodeURIComponent(value))));
export function renderToolsFor(type, value, box) { const types = type === "text" ? ["keyword"] : type === "url" ? ["url", "domain"] : [type]; const d = type === "url" ? domainOf(value) : value; const cats = FRAMEWORK.filter(c => c.tools && c.types.some(t => types.includes(t))); if (!cats.length) return box.innerHTML = ""; box.innerHTML = `<div class="card"><details ${type === "text" ? "" : "open"}><summary class="small b">🗂 OSINT ツール（${cats.length} カテゴリ、対象入りリンク）</summary>${cats.map(c => `<p class="small"><b>${esc(c.cat)}</b><br>${c.tools.map(t => t.kind === "link" && t.url ? `<a href="${esc(fillUrl(t.url, value.slice(0, 200), d))}" target="_blank" rel="noopener"><button class="small">${esc(t.name)}</button></a>` : `<span class="pill">${t.kind === "auto" ? "自動" : "端末内"}: ${esc(t.name)}</span>`).join(" ")}</p>`).join("")}</details></div>`; }

