/* ================= 聞く（文書に問う） ================= */
let docText = "", docLines = [];
function botSay(html) { const d = document.createElement("div"); d.className = "msg bot"; d.innerHTML = html; $("#chat").appendChild(d); $("#chat").scrollTop = 1e9; return d; }
function meSay(t) { const d = document.createElement("div"); d.className = "msg me"; d.textContent = t; $("#chat").appendChild(d); $("#chat").scrollTop = 1e9; }
let typingEl = null; function typing(on, msg) { if (on) { if (!typingEl) { typingEl = document.createElement("div"); typingEl.className = "msg bot typing"; $("#chat").appendChild(typingEl); } typingEl.textContent = msg || "判定中…"; $("#chat").scrollTop = 1e9; } else if (typingEl) { typingEl.remove(); typingEl = null; } }
export function setDoc(t) { docText = (t || "").trim(); $("#a-doc").value = docText; docLines = docText.split(/\n+|(?<=[。！？!?])\s*/).map(s => s.trim()).filter(Boolean); renderDoc(); }
function renderDoc(hits = []) { if ($("#a-doc").value.trim() !== docText) setDoc($("#a-doc").value); $("#a-view").innerHTML = docLines.map((l, i) => `<p class="${hits[0] === i ? "hit" : hits[1] === i ? "hit2" : ""}">${esc(l)}</p>`).join(""); $("#a-doc-info").textContent = docLines.length ? `${docLines.length} 行 ・ ${docText.length} 文字` : "文書は未設定"; if (docLines.length) $("#a-doc").style.display = "none"; }
$("#a-set").onclick = () => { setDoc($("#a-doc").value); if (docLines.length) botSay(`文書を受け取りました（${docLines.length} 行）。上のチップか、<code>? 質問</code> で聞いてください。`); };
$("#a-doc-clear").onclick = () => { docText = ""; docLines = []; $("#a-doc").value = ""; $("#a-doc").style.display = ""; renderDoc(); };
$("#a-quick").innerHTML = ASK_QUICK.map(q => `<span class="chip soft" data-t="${esc(q.text)}">${esc(q.label)}</span>`).join(""); $$("#a-quick .chip").forEach(c => c.onclick = () => { $("#c-in").value = c.dataset.t; $("#c-send").click(); });
function parseAsk(text) { let m; if ((m = /^[?？]\s*(.+)$/s.exec(text))) return { type: "noul", id: "q", instructions: m[1].trim() }; if ((m = /^(度合い|程度)[:：]\s*(.+)$/s.exec(text))) return { type: "score", id: "q", instructions: m[2].trim(), levels: ["0", "1", "2", "3", "4", "5"] }; if ((m = /^(どの行|どこ)[:：]\s*(.+)$/s.exec(text))) return { line: true, instructions: m[2].trim() }; if (text.includes("|")) { const p = text.split("|").map(s => s.trim()).filter(Boolean); if (p.length >= 3) return { type: "choice", id: "q", instructions: p[0], options: p.slice(1) }; } if (/[かか？?]$/.test(text)) return { type: "noul", id: "q", instructions: text }; return null; }
async function askHandle(text) { if (!docLines.length) { setDoc(text); return botSay(`これを文書として置きました（${docLines.length} 行）。次に <code>? 質問</code> や「どの行: 内容」で聞いてください。`); } const q = parseAsk(text); if (!q) return botSay("書き方：<code>? 返信が必要か</code>／<code>担当は | 請求 | 配送</code>／<code>度合い: 緊急度</code>／<code>どの行: 避難所の場所</code>。文書を差し替えるには左で「消す」→ 貼る。"); if (!ready()) return;
  if (q.line) { const N = Math.min(docLines.length, 30); const opts = docLines.slice(0, N).map((l, i) => `${i + 1}: ${l.slice(0, 60)}`); const qq = { type: "choice", id: "line", instructions: `次の内容が書かれている行はどれか: ${q.instructions}`, options: [...opts, "該当なし"] }; typing(true, `行を探しています…（${N} 行）`); const r = await jev.decide(docText.slice(0, 1500), [qq], null, curOpts()); bump(1, r.latency_ms); const a = r.answers[0]; const d = a.distribution; const ranked = d.labels.map((l, i) => [i, d.probabilities[i]]).sort((x, y) => y[1] - x[1]); const hits = ranked.filter(([i]) => i < N).slice(0, 2).map(([i]) => i); const none = a.choice === "該当なし"; renderDoc(none ? [] : hits);
    return botSay(`<div class="big">${none ? "該当なし" : `${hits[0] + 1} 行目`}</div>${none ? "" : `<div class="small">${esc(docLines[hits[0]])}</div>`}<div class="meta">確信 ${pc(a.confidence)}${hits[1] != null && !none ? ` ・ 次点 ${hits[1] + 1} 行目（${pc(ranked[1][1])}）` : ""}${docLines.length > N ? ` ・ 先頭 ${N} 行のみ対象` : ""} ・ ${r.latency_ms.toFixed(0)} ms</div>`); }
  typing(true, "判定中…"); const r = await jev.decide(docText.slice(0, 1500), [q], null, curOpts()); bump(1, r.latency_ms); const a = r.answers[0]; const v = a.type === "choice" ? esc(a.choice) : a.type === "score" ? `${esc(a.level)} / 5` : (a.noul ? "はい" : "いいえ");
  const el = botSay(`<div class="small muted">${esc(q.instructions)}</div><div class="big">${v} <span class="conf ${confCls(a.confidence)}">${pc(a.confidence)}</span></div><div class="dist">${a.distribution.labels.map((l, i) => `<span>${esc(l)}</span><div class="bar"><i style="width:${a.distribution.probabilities[i] * 100}%"></i></div><span>${(a.distribution.probabilities[i] * 100).toFixed(0)}%</span>`).join("")}</div><div class="meta">${esc(jev.name)} ・ ${r.latency_ms.toFixed(0)} ms ・ 端末内</div><div class="acts"><button class="c-where">どの行が根拠？</button></div>`); el.querySelector(".c-where").onclick = () => { $("#c-in").value = "どの行: " + q.instructions; $("#c-send").click(); }; }
let chatBusy = false; const askLog = [];
$("#c-send").onclick = async () => { const t = $("#c-in").value.trim(); if (!t) return; if (chatBusy) return toast("判定中です"); meSay(t); askLog.push({ me: t }); $("#c-in").value = ""; $("#c-in").style.height = "auto"; chatBusy = true; $("#c-send").disabled = true; try { await askHandle(t); askLog.push({ bot: $("#chat").lastElementChild?.textContent }); } catch (e) { botSay("エラー: " + esc(e.message)); } typing(false); chatBusy = false; $("#c-send").disabled = !jev; };
$("#c-in").onkeydown = e => { if (e.key === "Enter" && !e.shiftKey && !isMobile) { e.preventDefault(); $("#c-send").click(); } }; $("#c-in").oninput = () => { const t = $("#c-in"); t.style.height = "auto"; t.style.height = Math.min(120, t.scrollHeight) + "px"; };
$("#c-clear").onclick = () => { $("#chat").innerHTML = ""; askLog.length = 0; }; $("#c-save").onclick = () => download(`ask-${Date.now()}.json`, JSON.stringify({ version: VERSION, model: jev?.name, doc: docText, log: askLog }, null, 1));
$("#a-doc").oninput = () => { $("#a-doc-info").textContent = ""; };

