const incoming = parseIncoming();
async function handleIncoming() { if (!incoming) return; const inc = incoming; if (inc.q) { $("#u-q").value = inc.q; uModeSel = "topic"; if (inc.run !== "0") $("#u-run").click(); return; } if (inc.target) { $("#u-q").value = inc.target; uModeSel = "target"; if (inc.run !== "0") $("#u-run").click(); return; }
  const text = [inc.title, inc.text].filter(Boolean).join("\n").trim() || inc.url || ""; if (!text) return; const t = TEMPLATES.find(x => x.id === inc.tmpl); if (t) { setQuestions(t.questions, true); $("#p-ctx").value = t.context.join("\n"); } $("#p-state").value = text; if (inc.url && !text.includes(inc.url)) $("#p-ctx").value = [...ctx(), "出典 URL: " + inc.url].join("\n"); if (inc.ctx) $("#p-ctx").value = [...ctx(), inc.ctx].join("\n"); $("#p-ctx").oninput(); showTab("verify"); toast("共有された文章を受け取りました"); if (inc.run === "1") { await waitModel(); if (jev) $("#p-run").click(); } }

